import{_ as e,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Lembrar dicas do eproc já fechadas","description":"","frontmatter":{"title":"Lembrar dicas do eproc já fechadas","id":"eproc-lembrar-dicas-fechadas","plataforma":"eproc","grupo":"Menu superior","plano":"free","desde":"1.8.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-lembrar-dicas-fechadas.md","filePath":"funcionalidades/eproc-lembrar-dicas-fechadas.md"}'),d={name:"funcionalidades/eproc-lembrar-dicas-fechadas.md"};function c(i,a,t,l,n,u){return o(),r("div",null,a[0]||(a[0]=[s('<h1 id="lembrar-dicas-do-eproc-ja-fechadas" tabindex="-1">Lembrar dicas do eproc já fechadas <a class="header-anchor" href="#lembrar-dicas-do-eproc-ja-fechadas" aria-label="Permalink to &quot;Lembrar dicas do eproc já fechadas&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>O eproc mostra dicas próprias na tela, mas costuma esquecer quais você já viu e as repete. Este recurso guarda as dicas que você já fechou e não as deixa aparecer de novo. Todas as dicas guardadas ficam reunidas num painel, para consulta.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><ul><li><strong>eproc</strong>, em qualquer tela onde o eproc exiba uma dica.</li><li><strong>eproc</strong>, botão de ajuda (&quot;?&quot;) do menu superior, que passa a mostrar o logo do eploc e abre o painel de dicas já vistas. O item &quot;Rever dica&quot; do menu de ajuda também abre esse painel.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Quando uma dica do eproc aparecer, leia e feche-a no &quot;×&quot; (ou espere o temporizador dela acabar). A partir daí, ela não volta a aparecer.</li><li>Para rever uma dica, clique no botão de ajuda (&quot;?&quot;) do menu superior. O painel lista as dicas guardadas, agrupadas por assunto.</li><li>Para voltar a ver todas as dicas, clique em <strong>Mostrar todas as dicas de novo</strong> no painel e confirme com um segundo clique. O eproc volta a exibi-las normalmente.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A dica é reconhecida pelo identificador e pelo título que o eproc lhe dá. Se o eproc mudar o título de uma dica, ela é tratada como nova e aparece mais uma vez.</li><li>As dicas guardadas acompanham as configurações sincronizadas do navegador (perfil do Chrome ou Edge), e não a conta do eproc.</li></ul>',11)]))}const h=e(d,[["render",c]]);export{m as __pageData,h as default};
